insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('MATH-CNT-01','mathematics','Counting','Count up to 3 objects','Touch each object once while saying number words 1, 2, 3.','little-explorer','["Touches each item once","Says number words in order","Knows the last word tells how many"]'::jsonb,'{"priorKnowledge":"Hears number words in songs and play.","examples":["Count 3 apples on a plate","Count 2 shoes"],"activityTypes":["count-collect","tap-choose"],"commonDifficulties":["Counts the same item twice","Skips items","Recites numbers without touching"],"hints":["Touch each one as you count.","Start at one end so you don''t miss any."],"nextSteps":["MATH-CNT-02"],"parentExplanation":"Counting small groups by touching each object builds one-to-one correspondence, the foundation of all number work.","offlineIdea":"Count the spoons as you lay the table."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('MATH-CNT-02','mathematics','Counting','Count up to 5 and say how many','Count up to five objects and understand the last number says the total.','little-explorer','["Counts accurately to 5","Answers ''how many?'' with the last number counted"]'::jsonb,'{"priorKnowledge":"Counts to 3 reliably.","examples":["Count 5 ducks","Count 4 balloons"],"activityTypes":["count-collect"],"commonDifficulties":["Counts again when asked ''how many?''","Loses place in a scattered group"],"hints":["Say the numbers slowly as you touch.","The last number you say is how many there are."],"nextSteps":["MATH-CNT-03","MATH-ADD-01"],"parentExplanation":"Understanding that the last number counted tells ''how many'' (cardinality) is a key milestone, more important than reciting to 100.","offlineIdea":"Count 5 grapes together, then eat the last one!"}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('MATH-CNT-03','mathematics','Counting','Count up to 10','Count up to ten objects in a scattered group without missing any.','little-explorer','["Counts accurately to 10","Uses a system (moving along, tapping each)"]'::jsonb,'{"priorKnowledge":"Counts to 5 reliably.","examples":["Count 8 animals in a field"],"activityTypes":["count-collect"],"commonDifficulties":["Double counting in larger groups","Number-name sequence slips around 7–9"],"hints":["Count from left to right.","Tap each one so you know it is counted."],"nextSteps":["MATH-NUM-02"],"parentExplanation":"Counting larger groups needs a strategy for keeping track. Notice whether your child moves objects or points systematically.","offlineIdea":"Count the stairs as you climb."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('MATH-NUM-01','mathematics','Number recognition','Recognise numerals 1–5 and match to quantity','Link the written numeral to a quantity of objects.','little-explorer','["Matches numerals 1–5 to the right quantity"]'::jsonb,'{"priorKnowledge":"Counts to 3.","examples":["Match numeral 4 to four dots"],"activityTypes":["match-pair"],"commonDifficulties":["Confuses 6/9 later; at this stage 2/5 or 1/7"],"hints":["Count the dots, then look for that number."],"nextSteps":["MATH-NUM-02"],"parentExplanation":"Connecting the symbol to a quantity is the bridge from concrete counting to abstract number.","offlineIdea":"Spot numbers on doors, buses and clocks."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('MATH-NUM-02','mathematics','Number recognition','Know the order of numbers 1–10','Put numbers in order and find a missing number in a sequence.','little-explorer','["Orders numerals 1–5","Fills a one-number gap"]'::jsonb,'{"priorKnowledge":"Recognises numerals to 5.","examples":["Order 1–5 on a train","Find the missing number in 1, 2, _, 4"],"activityTypes":["complete-pattern","match-pair"],"commonDifficulties":["Swaps neighbouring numbers"],"hints":["What number comes after 2?","Count from 1 and see where it stops."],"nextSteps":["MATH-ADD-01"],"parentExplanation":"Number order is the early number line; it later supports adding and subtracting.","offlineIdea":"Hop along numbers drawn in chalk."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('MATH-CMP-01','mathematics','Comparing','Compare groups: more, fewer, the same','Say which of two groups has more or fewer without needing exact counts.','little-explorer','["Chooses the larger group","Chooses the smaller group when asked"]'::jsonb,'{"priorKnowledge":"Knows ''more'' from daily life.","examples":["Which plate has more biscuits?"],"activityTypes":["tap-choose"],"commonDifficulties":["Judges by space taken rather than number","Mixes up more and fewer"],"hints":["Line them up side by side.","Count each group and compare."],"nextSteps":["MATH-SUB-02"],"parentExplanation":"Comparing groups builds ''number sense''. Spread-out groups look bigger, which is a classic puzzle at this age.","offlineIdea":"Share biscuits and ask ''who has more?''"}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('MATH-SUB-01','mathematics','Counting','Give me exactly N','Hand over a requested number of objects and stop at the right number.','little-explorer','["Stops at the requested number","Corrects if too many"]'::jsonb,'{"priorKnowledge":"Counts to 5.","examples":["Give the dinosaur 3 apples"],"activityTypes":["count-collect"],"commonDifficulties":["Keeps going past the number","Counts the objects already given"],"hints":["Count out loud as you give.","Stop when you say the number you need."],"nextSteps":["MATH-ADD-01"],"parentExplanation":"''Give me 3'' tests that your child can use counting to build a quantity, harder than counting what is already there.","offlineIdea":"Ask for ''two socks'' or ''four blocks''."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('MATH-SUB-02','mathematics','Early arithmetic','Taking one away leaves fewer','See that when one object goes away, fewer are left.','little-explorer','["Chooses the group that shows what is left"]'::jsonb,'{"priorKnowledge":"Compares groups.","examples":["3 ducks, 1 swims away: 2 are left"],"activityTypes":["tap-choose"],"commonDifficulties":["Forgets the starting number"],"hints":["How many were there at first?","One went away, so there is one fewer."],"nextSteps":["MATH-ADD-01"],"parentExplanation":"Concrete take-away with pictures prepares for subtraction without any written sums.","offlineIdea":"Eat one grape from a bunch, how many now?"}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('MATH-SRT-01','mathematics','Sorting','Sort by one feature (size or colour)','Put things into groups by one clear property.','little-explorer','["Sorts items correctly into two groups by size or colour"]'::jsonb,'{"priorKnowledge":"Knows big and small.","examples":["Big and small teddies in two baskets"],"activityTypes":["match-pair"],"commonDifficulties":["Changes the sorting rule midway"],"hints":["Look at just the size.","Is this one big or small?"],"nextSteps":["LOG-CLS-01"],"parentExplanation":"Sorting by a single rule is the start of classification and data handling.","offlineIdea":"Sort the laundry by size or colour."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('MATH-SHP-01','mathematics','Shape','Spot circles, squares and triangles','Recognise basic 2D shapes in pictures and everyday things.','little-explorer','["Chooses the named shape among distractors"]'::jsonb,'{"priorKnowledge":"Plays with blocks.","examples":["A clock is a circle"],"activityTypes":["tap-choose"],"commonDifficulties":["Calls any pointy shape a triangle"],"hints":["Count the sides.","Does it have corners?"],"nextSteps":["LOG-SPA-01"],"parentExplanation":"Naming shapes in the real world links maths to your child''s surroundings.","offlineIdea":"Go on a shape hunt around the house."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('MATH-PAT-01','mathematics','Patterns','Continue a repeating pattern','Notice what repeats and say what comes next in an AB pattern.','little-explorer','["Chooses the correct next item in an AB pattern"]'::jsonb,'{"priorKnowledge":"Matches colours.","examples":["Red, blue, red, blue, ?"],"activityTypes":["complete-pattern"],"commonDifficulties":["Picks a favourite colour regardless of pattern"],"hints":["Say the colours out loud.","What came after red before?"],"nextSteps":["LOG-PAT-01"],"parentExplanation":"Patterns are the root of algebraic thinking.","offlineIdea":"Thread beads in a repeating pattern."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('MATH-ADD-01','mathematics','Early arithmetic','Add within 5 using objects','Combine two small groups and say the total.','curious-thinker','["Combines groups and states the total"]'::jsonb,'{"priorKnowledge":"Counts to 5 reliably.","examples":["2 apples and 1 apple make 3"],"activityTypes":["count-collect"],"commonDifficulties":["Counts only one group"],"hints":["Count them all together."],"nextSteps":["MATH-BND-01"],"parentExplanation":"Planned: concrete addition stories.","offlineIdea":null}'::jsonb,'draft') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('MATH-BND-01','mathematics','Number bonds','Number bonds to 5','Know pairs of numbers that make 5.','curious-thinker','["States complementary pairs to 5"]'::jsonb,'{"priorKnowledge":"Adds within 5.","examples":["2 and 3 make 5"],"activityTypes":["tap-choose"],"commonDifficulties":["Guessing"],"hints":["Use fingers."],"nextSteps":[],"parentExplanation":"Planned: bonds are the basis of mental arithmetic.","offlineIdea":null}'::jsonb,'draft') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('MATH-EST-01','mathematics','Estimation','Estimate ''about how many''','Make a sensible guess about a group before counting.','curious-thinker','["Estimates within a sensible range"]'::jsonb,'{"priorKnowledge":"Counts to 10.","examples":["About how many sweets?"],"activityTypes":["tap-choose"],"commonDifficulties":["Wild guesses"],"hints":["Think of a small group you know."],"nextSteps":[],"parentExplanation":"Planned: estimation builds number sense.","offlineIdea":null}'::jsonb,'draft') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('MATH-PLV-01','mathematics','Place value','Tens and ones to 20','Understand a number as groups of ten and some ones.','confident-learner','["Builds teen numbers from ten and ones"]'::jsonb,'{"priorKnowledge":"Counts to 20.","examples":["13 is one ten and three ones"],"activityTypes":["count-collect"],"commonDifficulties":["Reversing digits"],"hints":["Make a group of ten first."],"nextSteps":[],"parentExplanation":"Planned for the Confident Learner band.","offlineIdea":null}'::jsonb,'draft') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('MATH-WRD-01','mathematics','Word problems','Solve simple one-step word stories','Use a story to decide whether to add or take away.','young-problem-solver','["Chooses the right operation and answers"]'::jsonb,'{"priorKnowledge":"Adds and subtracts within 10.","examples":["Sam had 4 stickers and got 3 more"],"activityTypes":["listen-respond"],"commonDifficulties":["Choosing the wrong operation"],"hints":["Draw it."],"nextSteps":[],"parentExplanation":"Planned for the Young Problem Solver band.","offlineIdea":null}'::jsonb,'draft') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('SPE-VOC-01','spoken-english','Vocabulary','Name everyday things','Say or point to the names of common objects, animals and foods.','little-explorer','["Links spoken word to the right picture"]'::jsonb,'{"priorKnowledge":"Uses single words.","examples":["Tap the banana"],"activityTypes":["tap-choose"],"commonDifficulties":["Similar-looking items"],"hints":["Say the word slowly."],"nextSteps":["SPE-VOC-02"],"parentExplanation":"A wide vocabulary is one of the strongest early predictors of later reading comprehension. Talk about new words!","offlineIdea":"Name five things you can see on a walk."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('SPE-VOC-02','spoken-english','Vocabulary','Use describing words','Use adjectives such as big, soft, sweet, fast to describe things.','little-explorer','["Uses at least one describing word"]'::jsonb,'{"priorKnowledge":"Names things.","examples":["A soft teddy"],"activityTypes":["listen-respond"],"commonDifficulties":["Only names, doesn''t describe"],"hints":["How does it feel? How does it look?"],"nextSteps":["SPE-SNT-01"],"parentExplanation":"Describing words make speech richer. Model them in everyday talk.","offlineIdea":"Describe a fruit: colour, feel, taste."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('SPE-SNT-01','spoken-english','Sentences','Say a whole sentence about a picture','Describe what is in a picture in a short sentence.','little-explorer','["Says a subject + action sentence"]'::jsonb,'{"priorKnowledge":"Names things.","examples":["The dog is running."],"activityTypes":["listen-respond"],"commonDifficulties":["Single words only"],"hints":["Who is in the picture? What are they doing?"],"nextSteps":["SPE-SNT-02","CONV-RSN-01"],"parentExplanation":"Gently modelling a fuller sentence back works better than correcting.","offlineIdea":"Describe a picture in a book together."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('SPE-VRB-01','spoken-english','Vocabulary','Use action words','Say what people and animals are doing.','little-explorer','["Uses a suitable action word"]'::jsonb,'{"priorKnowledge":"Names things.","examples":["jumping, sleeping, eating"],"activityTypes":["listen-respond"],"commonDifficulties":["Uses nouns only"],"hints":["What are they doing with their body?"],"nextSteps":["SPE-SNT-01"],"parentExplanation":"Verbs bring sentences to life.","offlineIdea":"Play charades with actions."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('SPE-SNT-02','spoken-english','Sentences','Finish a sentence sensibly','Pick or say the word that makes a sentence make sense.','little-explorer','["Selects a word that fits meaning and grammar"]'::jsonb,'{"priorKnowledge":"Understands short sentences.","examples":["A fish can ___ (swim)"],"activityTypes":["tap-choose"],"commonDifficulties":["Picks by picture only"],"hints":["Say the whole sentence."],"nextSteps":["CONV-RSN-01"],"parentExplanation":"Completing sentences builds grammar and meaning together.","offlineIdea":"Pause before the last word of a familiar rhyme."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('SPE-LIS-01','spoken-english','Listening','Listen and respond to a request or question','Listen to a short spoken instruction and respond.','little-explorer','["Responds to the spoken request"]'::jsonb,'{"priorKnowledge":"Follows simple instructions.","examples":["Tap the red ball"],"activityTypes":["listen-respond","tap-choose"],"commonDifficulties":["Distracted"],"hints":["Press the ear to hear it again."],"nextSteps":[],"parentExplanation":"Active listening comes before speaking well.","offlineIdea":"Give two-step instructions: ''Get your shoes and bring the bag''."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('CONV-RSP-01','conversation','Responding','Respond to a question on topic','Answer a question with something relevant.','little-explorer','["Gives a relevant answer"]'::jsonb,'{"priorKnowledge":"Speaks in short sentences.","examples":["''What is your favourite fruit?'' ''Mango.''"],"activityTypes":["listen-respond"],"commonDifficulties":["Off-topic answers","Silence"],"hints":["You can tap a picture or tell me in your own words."],"nextSteps":["CONV-OPN-01","CONV-TRN-01"],"parentExplanation":"There are no wrong answers here, just practice answering and being heard.","offlineIdea":"Ask open questions at mealtimes."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('CONV-OPN-01','conversation','Opinions','Say what you like and why','Express a preference and add a describing word or reason.','little-explorer','["States a preference","Adds a detail"]'::jsonb,'{"priorKnowledge":"Names favourites.","examples":["I like mangoes because they are sweet."],"activityTypes":["listen-respond"],"commonDifficulties":["One-word answers"],"hints":["Tell me what you like about it."],"nextSteps":["CONV-RSN-01"],"parentExplanation":"Preferences are a safe, motivating way to practise longer answers.","offlineIdea":"Ask ''what was your favourite part?'' after outings."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('CONV-TRN-01','conversation','Turn-taking','Take turns and ask back','Listen, answer, then ask the other person a question.','little-explorer','["Replies and asks something back"]'::jsonb,'{"priorKnowledge":"Answers questions.","examples":["''I''m Sam. What''s your name?''"],"activityTypes":["listen-respond"],"commonDifficulties":["Waits to be asked"],"hints":["Now you can ask me something."],"nextSteps":["CONV-QST-01"],"parentExplanation":"Two-way conversation is a foundation for friendships.","offlineIdea":"Play a question ping-pong game."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('CONV-QST-01','conversation','Questions','Ask a question','Ask who, what, why or where questions out of curiosity.','little-explorer','["Asks a relevant question"]'::jsonb,'{"priorKnowledge":"Answers questions.","examples":["''Why is the moon out?''"],"activityTypes":["listen-respond"],"commonDifficulties":["Statements instead of questions"],"hints":["What would you like to know?"],"nextSteps":["CONV-RSN-01"],"parentExplanation":"Curiosity is the engine of learning; celebrate every ''why?''.","offlineIdea":"Think of three questions to ask grandparents."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('CONV-RSN-01','conversation','Reasoning','Give a simple reason with ''because''','Explain a choice or a fact using because.','little-explorer','["Gives a reason, in any form"]'::jsonb,'{"priorKnowledge":"States preferences.","examples":["I wear a coat because it is cold."],"activityTypes":["listen-respond"],"commonDifficulties":["Repeats the answer instead of explaining"],"hints":["Why do you think so?"],"nextSteps":[],"parentExplanation":"Explaining ''why'' is the start of reasoning. Accept any sensible reason.","offlineIdea":"Ask ''why do you think that?'' about everyday things."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('CONV-NAR-01','conversation','Narrating','Tell about something that happened','Talk about an event or part of the day in order.','little-explorer','["Describes at least one event"]'::jsonb,'{"priorKnowledge":"Answers questions.","examples":["First we went to the park, then we had a snack."],"activityTypes":["listen-respond"],"commonDifficulties":["Mixes up order"],"hints":["What did you do first?"],"nextSteps":["LIT-NAR-01"],"parentExplanation":"Narrating events builds the language of stories. We do not keep what your child says.","offlineIdea":"Chat about the day at bedtime."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('CONV-NAR-02','conversation','Narrating','Say what might happen next','Predict an outcome and talk about it.','little-explorer','["Offers a sensible prediction"]'::jsonb,'{"priorKnowledge":"Answers questions.","examples":["The balloon might float away."],"activityTypes":["listen-respond"],"commonDifficulties":["Says ''I don''t know''"],"hints":["What do you think will happen?"],"nextSteps":[],"parentExplanation":"Predicting links language with thinking ahead.","offlineIdea":"Pause a story and ask ''what next?''"}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LOG-MTC-01','logic-puzzles','Matching','Match things that go together','Match identical or related pictures.','little-explorer','["Matches pairs"]'::jsonb,'{"priorKnowledge":"Matches colours.","examples":["Shoe and sock"],"activityTypes":["match-pair"],"commonDifficulties":["Rushing"],"hints":["Look at one picture. What goes with it?"],"nextSteps":["LOG-ODD-01"],"parentExplanation":"Matching strengthens visual discrimination.","offlineIdea":"Match socks from the laundry."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LOG-ODD-01','logic-puzzles','Classification','Spot the odd one out','Find the item that doesn''t belong and know why.','little-explorer','["Picks the different item"]'::jsonb,'{"priorKnowledge":"Sorts by one feature.","examples":["Three fruits and a car"],"activityTypes":["tap-choose"],"commonDifficulties":["Picks by colour only"],"hints":["What do most of them have in common?"],"nextSteps":["LOG-CLS-01"],"parentExplanation":"Odd-one-out puzzles need flexible thinking about categories.","offlineIdea":"Play ''which one is different?'' with toys."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LOG-CLS-01','logic-puzzles','Classification','Sort into groups by category','Sort things by what they are (e.g. land and water animals).','little-explorer','["Sorts by category"]'::jsonb,'{"priorKnowledge":"Sorts by size or colour.","examples":["Fish go in water"],"activityTypes":["match-pair"],"commonDifficulties":["Switching rule"],"hints":["Where does this one live?"],"nextSteps":[],"parentExplanation":"Categorising is how we organise knowledge.","offlineIdea":"Sort toys into categories."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LOG-MEM-01','logic-puzzles','Memory','Notice what has changed or is missing','Remember a small set of objects and spot a missing one.','little-explorer','["Identifies the missing item"]'::jsonb,'{"priorKnowledge":"Names objects.","examples":["Which toy is missing?"],"activityTypes":["tap-choose"],"commonDifficulties":["Forgets quickly"],"hints":["Say the names to help you remember."],"nextSteps":[],"parentExplanation":"Visual memory grows with practice and naming items aloud.","offlineIdea":"Hide one toy from a row of four."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LOG-SEQ-01','logic-puzzles','Sequencing','Put events in order','Order what happens first, next and last.','little-explorer','["Orders 3–4 steps"]'::jsonb,'{"priorKnowledge":"Knows daily routines.","examples":["Wake up, brush teeth, eat breakfast"],"activityTypes":["complete-pattern"],"commonDifficulties":["Swaps middle steps"],"hints":["What happens first?"],"nextSteps":["LIT-NAR-01"],"parentExplanation":"Sequencing underlies stories, routines and instructions.","offlineIdea":"Talk through the steps of making toast."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LOG-PAT-01','logic-puzzles','Patterns','Continue a longer pattern','Continue AAB and ABC patterns.','little-explorer','["Continues the pattern"]'::jsonb,'{"priorKnowledge":"Continues AB patterns.","examples":["Star, star, moon, star, star, ?"],"activityTypes":["complete-pattern"],"commonDifficulties":["Treats it as AB"],"hints":["Say the pattern out loud from the start."],"nextSteps":[],"parentExplanation":"More complex patterns stretch working memory.","offlineIdea":"Make clapping patterns."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LOG-SPA-01','logic-puzzles','Spatial reasoning','Use position and shape to solve a puzzle','Match shadows and follow a simple route.','little-explorer','["Matches shapes to outlines","Chooses a path that reaches the goal"]'::jsonb,'{"priorKnowledge":"Knows shapes.","examples":["Match an animal to its shadow"],"activityTypes":["match-pair","tap-choose"],"commonDifficulties":["Mirrored shapes"],"hints":["Look at the outline."],"nextSteps":[],"parentExplanation":"Spatial skills predict later STEM success; puzzles and blocks are ideal.","offlineIdea":"Make shadows with a torch."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LOG-CAU-01','logic-puzzles','Cause and effect','Say what happens when...','Link an action to its effect.','little-explorer','["Chooses the likely result"]'::jsonb,'{"priorKnowledge":"Everyday experiences.","examples":["Sun melts ice cream"],"activityTypes":["tap-choose"],"commonDifficulties":["Unfamiliar situations"],"hints":["What happened the last time?"],"nextSteps":[],"parentExplanation":"Cause and effect is the root of scientific thinking.","offlineIdea":"Predict then test: does it float?"}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LOG-RUL-01','logic-puzzles','Rules','Discover a hidden rule','Work out the rule that links several items.','curious-thinker','["States or applies the rule"]'::jsonb,'{"priorKnowledge":"Odd one out.","examples":["All these are red things"],"activityTypes":["tap-choose"],"commonDifficulties":["Guessing"],"hints":["What is the same?"],"nextSteps":[],"parentExplanation":"Planned.","offlineIdea":null}'::jsonb,'draft') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LIT-RHY-01','early-literacy','Phonological awareness','Hear words that rhyme','Pick the word that rhymes with a given word.','little-explorer','["Selects a rhyming word"]'::jsonb,'{"priorKnowledge":"Knows nursery rhymes.","examples":["cat, hat"],"activityTypes":["tap-choose"],"commonDifficulties":["Picks a word with the same first sound"],"hints":["Listen to the ending."],"nextSteps":["LIT-PHN-01"],"parentExplanation":"Rhyme awareness is a key pre-reading skill.","offlineIdea":"Sing nursery rhymes and pause before the rhyming word."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LIT-PHN-01','early-literacy','Phonics','Hear the first sound in a word','Identify which word starts with a given sound.','little-explorer','["Chooses the word with the same first sound"]'::jsonb,'{"priorKnowledge":"Hears rhymes.","examples":["sun starts with sss"],"activityTypes":["tap-choose"],"commonDifficulties":["Letter names vs sounds"],"hints":["Say the word slowly."],"nextSteps":[],"parentExplanation":"Practise pure sounds (''sss'', ''mmm''), not letter names.","offlineIdea":"I spy with my little eye, using sounds."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
