insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LIT-NAR-01','early-literacy','Comprehension','Retell what happened in order','Put the events of a short story in order.','little-explorer','["Orders story events"]'::jsonb,'{"priorKnowledge":"Listens to stories.","examples":["First, next, last"],"activityTypes":["complete-pattern"],"commonDifficulties":["Mixes order"],"hints":["How did the story start?"],"nextSteps":[],"parentExplanation":"Retelling shows understanding.","offlineIdea":"Ask your child to retell a story to a toy."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('SCI-ANI-01','science-knowledge','Living things','Know where animals live','Match animals to their homes and habitats.','little-explorer','["Matches animals to homes"]'::jsonb,'{"priorKnowledge":"Knows common animals.","examples":["A bird lives in a nest"],"activityTypes":["match-pair"],"commonDifficulties":["Pets vs wild animals"],"hints":["Where would it sleep?"],"nextSteps":[],"parentExplanation":"Animal habitats introduce adaptation and environmental care.","offlineIdea":"Look for bugs and birds'' homes outdoors."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
