insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('SCI-NAT-01','science-knowledge','Plants','Know what plants need','Know plants need water, sun and soil to grow.','little-explorer','["Selects what a plant needs"]'::jsonb,'{"priorKnowledge":"Has seen plants.","examples":["Watering a plant"],"activityTypes":["tap-choose"],"commonDifficulties":["Thinks plants need milk"],"hints":["What do you give plants every day?"],"nextSteps":[],"parentExplanation":"Growing a plant at home makes this real.","offlineIdea":"Plant a bean in a jar and observe it each day."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('SCI-WTH-01','science-knowledge','Weather','Know where rain comes from','Know rain falls from clouds.','little-explorer','["Chooses clouds"]'::jsonb,'{"priorKnowledge":"Has seen rain.","examples":["Clouds make rain"],"activityTypes":["tap-choose"],"commonDifficulties":["Thinks rain comes from the sky ''by itself''"],"hints":["Look up on a rainy day."],"nextSteps":[],"parentExplanation":"Introduces the water cycle in simple terms.","offlineIdea":"Watch steam from a kettle (adult only) and talk about clouds."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('SCI-WTH-02','science-knowledge','Weather','Choose clothes for the weather','Match weather to sensible clothes and activities.','little-explorer','["Chooses sensible clothes"]'::jsonb,'{"priorKnowledge":"Knows basic weather words.","examples":["Umbrella for rain"],"activityTypes":["tap-choose"],"commonDifficulties":["Ignores the weather"],"hints":["Is it hot or cold?"],"nextSteps":[],"parentExplanation":"Links science to daily life and self-care.","offlineIdea":"Look out of the window and decide what to wear."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
