insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('CRE-STY-01','creativity-storytelling','Storytelling','Add your own ideas to a story','Continue a story with imaginative ideas of the child''s own.','little-explorer','["Contributes an idea (any idea)"]'::jsonb,'{"priorKnowledge":"Listens to stories.","examples":["The bunny found a magic door..."],"activityTypes":["listen-respond"],"commonDifficulties":["Waiting to be told"],"hints":["What would you like to happen?"],"nextSteps":["CRE-END-01"],"parentExplanation":"There are no right answers: any idea is welcome.","offlineIdea":"Take turns adding a sentence to a made-up story."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
