insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('CRE-IMG-01','creativity-storytelling','Imagination','Invent a character or creature','Combine ideas to invent and describe something new.','little-explorer','["Describes an invented creature"]'::jsonb,'{"priorKnowledge":"Pretend play.","examples":["A rabbit with wings"],"activityTypes":["listen-respond"],"commonDifficulties":["Copying a known character"],"hints":["What would it look like? What can it do?"],"nextSteps":[],"parentExplanation":"Imagination is a skill that grows with use.","offlineIdea":"Draw a made-up animal together."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('SEL-EMO-01','social-emotional','Feelings','Name feelings from faces and situations','Name happy, sad, angry, scared and excited feelings.','little-explorer','["Names the feeling"]'::jsonb,'{"priorKnowledge":"Notices faces.","examples":["Crying means sad"],"activityTypes":["tap-choose"],"commonDifficulties":["Confuses scared and surprised"],"hints":["Look at the face."],"nextSteps":["SEL-EMP-01"],"parentExplanation":"Feelings words help children manage big emotions.","offlineIdea":"Name your own feelings out loud during the day."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('SEL-EMP-01','social-emotional','Empathy','Respond kindly to someone who needs help','Think of kind and safe ways to help.','little-explorer','["Chooses a kind and safe action"]'::jsonb,'{"priorKnowledge":"Names feelings.","examples":["Help a lost animal by asking a grown-up"],"activityTypes":["tap-choose"],"commonDifficulties":["Ignoring"],"hints":["How would they feel?"],"nextSteps":["SEL-PRB-01"],"parentExplanation":"Empathy grows when children think about others'' feelings.","offlineIdea":"Talk about how a character in a book feels."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('SEL-PRB-01','social-emotional','Everyday problems','Choose a kind, safe response to a problem','Use words, take turns, or ask a trusted adult for help.','little-explorer','["Chooses a kind or safe response"]'::jsonb,'{"priorKnowledge":"Names feelings.","examples":["Ask to have a turn"],"activityTypes":["tap-choose"],"commonDifficulties":["Hitting or grabbing as an impulse"],"hints":["What could you say?"],"nextSteps":[],"parentExplanation":"Practise ''use your words'' and asking a trusted adult for help.","offlineIdea":"Role-play a sharing problem with soft toys."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LIT-ALP-01','early-literacy','Alphabet','Recognise and name letters','Find and name letters in small groups, a few at a time.','little-explorer','["Picks the named letter from a few choices","Names the letter"]'::jsonb,'{"priorKnowledge":"Hears the alphabet song.","examples":["Find the letter B","Which letter is this?"],"activityTypes":["tap-choose","match-pair"],"commonDifficulties":["Mixing up b and d","Confusing similar capitals"],"hints":["Look at the shape. Say the letter name."],"nextSteps":["LIT-ALP-02"],"parentExplanation":"Letter recognition comes before reading. A few letters at a time is plenty.","offlineIdea":"Hunt for the first letter of your child''s name on signs and packets."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LIT-ALP-02','early-literacy','Alphabet','Match capital and small letters','Pair each capital letter with its small letter.','curious-thinker','["Pairs capital and small letters correctly"]'::jsonb,'{"priorKnowledge":"Recognises many letters.","examples":["Match A with a","Match B with b"],"activityTypes":["match-pair"],"commonDifficulties":["b and d","q and p"],"hints":["Look at the shape. Which small letter looks like this capital?"],"nextSteps":["LIT-ALP-03"],"parentExplanation":"Children meet both forms of a letter in books and signs, so they learn to link them.","offlineIdea":"Match letter magnets or cards, capital to small."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LIT-ALP-03','early-literacy','Alphabet','Know the order of the alphabet','Say which letter comes next, and put letters in order.','curious-thinker','["Names the missing letter","Orders a short run of letters"]'::jsonb,'{"priorKnowledge":"Sings the alphabet song.","examples":["What comes after C?","Put A B C D in order"],"activityTypes":["complete-pattern"],"commonDifficulties":["Losing the place in the middle of the alphabet"],"hints":["Sing the alphabet song quietly. What comes next?"],"nextSteps":["LIT-PHN-02"],"parentExplanation":"Alphabet order helps children find words in dictionaries and lists later on.","offlineIdea":"Sing the alphabet song and pause before a letter for your child to say it."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LIT-PHN-02','early-literacy','Phonics','Link letters to their first sounds','Match a letter to a picture that starts with its sound.','curious-thinker','["Chooses the picture that starts with the letter''s sound"]'::jsonb,'{"priorKnowledge":"Hears first sounds in words.","examples":["B is for ball","S is for sun"],"activityTypes":["tap-choose","match-pair"],"commonDifficulties":["Using the letter name instead of its sound"],"hints":["Say the word slowly. What sound do you hear first?"],"nextSteps":["LIT-SPL-01"],"parentExplanation":"Knowing letter sounds is the key that unlocks reading.","offlineIdea":"Play I spy with letter sounds."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LIT-SPL-01','early-literacy','Spelling','Build three-letter words','Choose the missing letter to spell a simple word such as cat.','confident-learner','["Chooses the letter that completes a simple word"]'::jsonb,'{"priorKnowledge":"Knows letter sounds.","examples":["c a ? with a picture of a cat"],"activityTypes":["complete-pattern","tap-choose"],"commonDifficulties":["Missing the middle vowel sound"],"hints":["Say the word slowly. Which sound is missing?"],"nextSteps":["LIT-WRD-02"],"parentExplanation":"Blending sounds into words is the first step of spelling and reading.","offlineIdea":"Use magnetic letters to build c-a-t, h-a-t, m-a-t."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LIT-WRD-02','early-literacy','Word reading','Read and spell simple words','Read short words and spell them by choosing the right letters.','young-problem-solver','["Picks the written word that matches a picture","Completes a short word"]'::jsonb,'{"priorKnowledge":"Builds three-letter words.","examples":["Which word says dog?","Spell sun"],"activityTypes":["tap-choose","complete-pattern"],"commonDifficulties":["Reversing letters","Guessing from the first letter only"],"hints":["Sound it out one letter at a time."],"nextSteps":[],"parentExplanation":"Reading short words builds fluency and confidence.","offlineIdea":"Label things around the house with word cards."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LIT-LST-02','early-literacy','Comprehension','Answer who, where and why about a story','Listen to a short story and answer questions about characters, places and reasons.','curious-thinker','["Answers who, what, where and why questions about a story"]'::jsonb,'{"priorKnowledge":"Remembers who and what.","examples":["Where did the rabbit hide? Why?"],"activityTypes":["story-listen"],"commonDifficulties":["Remembering only the last part"],"hints":["Think back to the story. Listen to the page again."],"nextSteps":["LIT-LST-03"],"parentExplanation":"Ask who, where and why questions as you read together.","offlineIdea":"Read a picture book and ask a question after each page."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LIT-LST-03','early-literacy','Comprehension','Understand feelings and reasons in a story','Work out how a character feels and why, using what happened in the story.','confident-learner','["Uses story events to say how a character feels and why"]'::jsonb,'{"priorKnowledge":"Answers who, where and why.","examples":["Why was Mia sad?"],"activityTypes":["story-listen"],"commonDifficulties":["Guessing without using the story"],"hints":["What happened to the character? How would you feel?"],"nextSteps":["LIT-LST-04"],"parentExplanation":"Understanding feelings in stories builds empathy and thoughtful reading.","offlineIdea":"Pause a story and ask how the character is feeling and why."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LIT-LST-04','early-literacy','Comprehension','Work out what a story means','Use clues to work out what will happen, or what the story teaches.','young-problem-solver','["Makes a sensible prediction or says what the story teaches"]'::jsonb,'{"priorKnowledge":"Understands feelings and reasons.","examples":["What do you think happens next? What did the fox learn?"],"activityTypes":["story-listen"],"commonDifficulties":["Choosing something that is not supported by the story"],"hints":["What clues did the story give you?"],"nextSteps":[],"parentExplanation":"Inference and prediction are the heart of understanding what we read.","offlineIdea":"Predict what happens next each time you turn a page."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LOG-MAZ-01','logic-puzzles','Mazes','Follow a short path to a goal','Walk a character along a short, simple path to the goal.','little-explorer','["Reaches the goal on a short path"]'::jsonb,'{"priorKnowledge":"Moves things on a screen with taps.","examples":["Help the mouse reach the cheese"],"activityTypes":["maze"],"commonDifficulties":["Tapping far away squares"],"hints":["Tap the square next to you."],"nextSteps":["LOG-MAZ-02"],"parentExplanation":"Following a path builds planning and early spatial skills.","offlineIdea":"Make a path with cushions for your child to walk."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LOG-MAZ-02','logic-puzzles','Mazes','Find a route with turns','Find the way through a small maze with a few turns and a dead end.','curious-thinker','["Finds the goal, backing out of a dead end"]'::jsonb,'{"priorKnowledge":"Follows a short path.","examples":["Find the way to the treasure"],"activityTypes":["maze"],"commonDifficulties":["Keeps walking into walls"],"hints":["Look ahead. Which way is open?"],"nextSteps":["LOG-MAZ-03"],"parentExplanation":"Backing out of a dead end is real problem solving: try, notice, try again.","offlineIdea":"Draw a simple maze on paper with a thick pen."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LOG-MAZ-03','logic-puzzles','Mazes','Plan a route in a bigger maze','Look ahead and plan a route through a bigger maze with several dead ends.','confident-learner','["Reaches the goal with few wrong turns"]'::jsonb,'{"priorKnowledge":"Finds routes through small mazes.","examples":["Plan the way before you walk"],"activityTypes":["maze"],"commonDifficulties":["Not looking ahead"],"hints":["Trace the way with your eyes before you move."],"nextSteps":["LOG-MAZ-04"],"parentExplanation":"Planning ahead is a skill that carries over to maths and everyday life.","offlineIdea":"Let your child try a paper maze with a finger before a pen."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LOG-MAZ-04','logic-puzzles','Mazes','Solve larger mazes by planning ahead','Solve a large maze by planning and backing out of dead ends.','young-problem-solver','["Solves a large maze, using planning"]'::jsonb,'{"priorKnowledge":"Plans routes in bigger mazes.","examples":["Solve a large maze"],"activityTypes":["maze"],"commonDifficulties":["Giving up at dead ends"],"hints":["Work back from the goal."],"nextSteps":[],"parentExplanation":"Working backwards from the goal is a powerful problem-solving strategy.","offlineIdea":"Try solving a paper maze from the finish back to the start."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LOG-SEQ-02','logic-puzzles','Sequences','Put longer sequences in order','Put five or six steps of a routine or story in order.','curious-thinker','["Orders five steps"]'::jsonb,'{"priorKnowledge":"Orders three or four steps.","examples":["Plant a seed: five steps"],"activityTypes":["complete-pattern"],"commonDifficulties":["Mixing up the middle steps"],"hints":["What must happen before this?"],"nextSteps":[],"parentExplanation":"Sequencing is the basis of following instructions and telling stories.","offlineIdea":"Talk through the steps of baking, planting or getting dressed."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LOG-PAT-02','logic-puzzles','Patterns','Number and growing patterns','Continue patterns that grow or count in steps.','confident-learner','["Continues a number or growing pattern"]'::jsonb,'{"priorKnowledge":"Continues repeating patterns.","examples":["2, 4, 6, ?","1, 2, 2, 3, 3, ?"],"activityTypes":["complete-pattern"],"commonDifficulties":["Looking only at the last item"],"hints":["How much does it go up each time?"],"nextSteps":[],"parentExplanation":"Counting in steps and growing patterns prepare children for multiplication and algebra.","offlineIdea":"Count in twos with socks or shoes."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LOG-RID-01','logic-puzzles','Reasoning','Solve simple riddles using clues','Use clues to work out what a riddle is about.','confident-learner','["Uses every clue to find the answer"]'::jsonb,'{"priorKnowledge":"Sorts things by their features.","examples":["I have wheels and I go on roads. What am I?"],"activityTypes":["tap-choose"],"commonDifficulties":["Stopping after the first clue"],"hints":["Use all the clues. Which choice fits every one?"],"nextSteps":["LOG-DED-01"],"parentExplanation":"Riddles teach children to hold several clues in mind at once.","offlineIdea":"Make up riddles about things in your house."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
insert into public.learning_objectives (id,domain_id,subdomain,title,description,age_band,success_criteria,details,status) values ('LOG-DED-01','logic-puzzles','Reasoning','Use clues to work out the answer','Use if-then clues to rule things out and find the answer.','young-problem-solver','["Rules choices out using clues"]'::jsonb,'{"priorKnowledge":"Solves simple riddles.","examples":["It is not red and it is not round. Which one is it?"],"activityTypes":["tap-choose"],"commonDifficulties":["Ignoring negative clues such as not"],"hints":["Cross out what the clues say it is not."],"nextSteps":[],"parentExplanation":"Ruling things out is the root of logical deduction.","offlineIdea":"Play twenty questions with yes-or-no answers."}'::jsonb,'published') on conflict (id) do update set title=excluded.title, description=excluded.description, success_criteria=excluded.success_criteria, details=excluded.details, status=excluded.status;
