hide them"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["How can everyone get a cookie?"]},{"id":"r2","prompt":"A new friend has no one to play with. What could you do?","display":"🧒","options":[{"id":"a","visual":"👋","alt":"ask them to play"},{"id":"b","visual":"🚶","alt":"walk away"},{"id":"c","visual":"🙈","alt":"ignore them"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["How would you feel if you were new?"]},{"id":"r3","prompt":"You both want to be first on the slide. What could you do?","display":"🛝","options":[{"id":"a","visual":"🔁","alt":"take turns"},{"id":"b","visual":"💪","alt":"push in front"},{"id":"c","visual":"😡","alt":"shout"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["Could you go one after the other?"]}]}'::jsonb,'published','reviewed',1,3) on conflict (id) do update set title=excluded.title, description=excluded.description, configuration=excluded.configuration, status=excluded.status, review_status=excluded.review_status, version=excluded.version, estimated_duration=excluded.estimated_duration;
