insert into public.activities (id,title,description,domain_id,world,engine_type,age_band,difficulty,configuration,status,review_status,version,estimated_duration) values ('story-the-lost-kitten','The Lost Kitten','Listen to a story about a lost kitten, then answer who, where and why questions.','early-literacy','conversation-cafe','story-listen','curious-thinker',2,'{"id":"story-the-lost-kitten","title":"The Lost Kitten","description":"Listen to a story about a lost kitten, then answer who, where and why questions.","world":"conversation-cafe","domain":"early-literacy","objectiveIds":["LIT-LST-02"],"ageBand":"curious-thinker","difficulty":2,"instructions":"Listen to the whole story. Then I will ask you some questions.","audioInstructions":"Listen to the whole story. Then I will ask you some questions.","estimatedMinutes":5,"feedback":{"correct":["Good thinking!","You noticed something interesting!","Lovely work!","Yes, you did it!"],"encourage":["Let''s try together.","Would you like a little hint?","Let''s look at it another way.","Nice try! One more go."],"complete":["You worked hard on that.","What a wonderful adventure!","Thank you for playing with me."]},"accessibility":{"requiresSpeech":false,"tapAlternative":true,"reducedMotionSafe":true},"media":[],"completion":{"minRoundsCompleted":2},"frameworkMappings":[{"frameworkId":"eyfs","reference":"Literacy","mappingType":"aligns"},{"frameworkId":"ncf-fs","reference":"Language and literacy","mappingType":"aligns"},{"frameworkId":"elof","reference":"Language and literacy","mappingType":"partial"}],"characterId":"otto","tags":["story","kindness"],"realWorldMission":"Ask your child: what would you do if you found a lost pet?","status":"published","reviewStatus":"reviewed","version":1,"presentation":"words","engine":"story-listen","rounds":[{"id":"p1","kind":"page","prompt":"Mira was walking in the park when she heard a tiny cry. Meow, meow!","display":"👧🌳","hints":[]},{"id":"p2","kind":"page","prompt":"She looked under a bench and found a little kitten. It was cold and scared.","display":"🐱😿","hints":[]},{"id":"p3","kind":"page","prompt":"Mira did not take the kitten away. She ran to ask a grown-up for help.","display":"👧🏃","hints":[]},{"id":"p4","kind":"page","prompt":"A kind lady read the name on the kitten''s collar. It said Mrs Rao, number five.","display":"👩🏷️","hints":[]},{"id":"p5","kind":"page","prompt":"Mira and the lady took the kitten home to Mrs Rao. Mrs Rao hugged her kitten and said thank you.","display":"🏠🐱💛","hints":[]},{"id":"q1","prompt":"Where did Mira find the kitten?","options":[{"id":"a","visual":"under a bench","alt":"under a bench"},{"id":"b","visual":"in a tree","alt":"in a tree"},{"id":"c","visual":"in a shop","alt":"in a shop"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["She looked under a bench and found a little kitten."],"kind":"question"},{"id":"q2","prompt":"Why was the kitten crying?","options":[{"id":"a","visual":"it was cold and scared","alt":"it was cold and scared"},{"id":"b","visual":"it was hungry for dinner","alt":"it was hungry for dinner"},{"id":"c","visual":"it wanted to play","alt":"it wanted to play"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["The story said the kitten was cold and scared."],"kind":"question"},{"id":"q3","prompt":"Who did Mira ask for help?","options":[{"id":"a","visual":"a grown-up","alt":"a grown-up"},{"id":"b","visual":"her best friend","alt":"her best friend"},{"id":"c","visual":"a bird","alt":"a bird"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["Mira ran to ask a grown-up for help. A grown-up is a safe person to ask."],"kind":"question"},{"id":"q4","prompt":"How did the story end?","options":[{"id":"a","visual":"the kitten went home to Mrs Rao","alt":"the kitten went home to Mrs Rao"},{"id":"b","visual":"Mira kept the kitten","alt":"Mira kept the kitten"},{"id":"c","visual":"the kitten ran away","alt":"the kitten ran away"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["They took the kitten home to Mrs Rao."],"kind":"question"}]}'::jsonb,'published','reviewed',1,5) on conflict (id) do update set title=excluded.title, description=excluded.description, configuration=excluded.configuration, status=excluded.status, review_status=excluded.review_status, version=excluded.version, estimated_duration=excluded.estimated_duration;
