insert into public.activities (id,title,description,domain_id,world,engine_type,age_band,difficulty,configuration,status,review_status,version,estimated_duration) values ('story-ravi-plants-a-seed','Ravi Plants a Seed','Listen to a story about growing a flower, then answer questions.','early-literacy','conversation-cafe','story-listen','curious-thinker',2,'{"id":"story-ravi-plants-a-seed","title":"Ravi Plants a Seed","description":"Listen to a story about growing a flower, then answer questions.","world":"conversation-cafe","domain":"early-literacy","objectiveIds":["LIT-LST-02"],"ageBand":"curious-thinker","difficulty":2,"instructions":"Listen to the whole story. Then I will ask you some questions.","audioInstructions":"Listen to the whole story. Then I will ask you some questions.","estimatedMinutes":5,"feedback":{"correct":["Good thinking!","You noticed something interesting!","Lovely work!","Yes, you did it!"],"encourage":["Let''s try together.","Would you like a little hint?","Let''s look at it another way.","Nice try! One more go."],"complete":["You worked hard on that.","What a wonderful adventure!","Thank you for playing with me."]},"accessibility":{"requiresSpeech":false,"tapAlternative":true,"reducedMotionSafe":true},"media":[],"completion":{"minRoundsCompleted":2},"frameworkMappings":[{"frameworkId":"eyfs","reference":"Literacy","mappingType":"aligns"},{"frameworkId":"ncf-fs","reference":"Language and literacy","mappingType":"aligns"},{"frameworkId":"elof","reference":"Language and literacy","mappingType":"partial"}],"characterId":"otto","tags":["story","plants","sequence"],"status":"published","reviewStatus":"reviewed","version":1,"presentation":"words","engine":"story-listen","rounds":[{"id":"p1","kind":"page","prompt":"Ravi found a small seed. He pushed it into a pot of soil.","display":"🧒🌰","hints":[]},{"id":"p2","kind":"page","prompt":"Every morning, Ravi gave the seed a little water, because plants need water to grow.","display":"💧🪴","hints":[]},{"id":"p3","kind":"page","prompt":"For many days nothing happened. Ravi waited and waited.","display":"⏳","hints":[]},{"id":"p4","kind":"page","prompt":"Then one morning he saw a tiny green sprout!","display":"🌱","hints":[]},{"id":"p5","kind":"page","prompt":"Soon the sprout grew leaves, and then a bright yellow flower. Ravi smiled the biggest smile.","display":"🌻😊","hints":[]},{"id":"q1","prompt":"What did Ravi plant?","options":[{"id":"a","visual":"a seed","alt":"a seed"},{"id":"b","visual":"a stone","alt":"a stone"},{"id":"c","visual":"a toy","alt":"a toy"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["Ravi found a small seed."],"kind":"question"},{"id":"q2","prompt":"Why did Ravi give the seed water?","options":[{"id":"a","visual":"plants need water to grow","alt":"plants need water to grow"},{"id":"b","visual":"the soil was dirty","alt":"the soil was dirty"},{"id":"c","visual":"he was thirsty","alt":"he was thirsty"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["The story said: plants need water to grow."],"kind":"question"},{"id":"q3","prompt":"What did Ravi see first?","options":[{"id":"a","visual":"a tiny green sprout","alt":"a tiny green sprout"},{"id":"b","visual":"a yellow flower","alt":"a yellow flower"},{"id":"c","visual":"a big tree","alt":"a big tree"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["Before the flower, he saw something tiny and green."],"kind":"question"},{"id":"q4","prompt":"How did Ravi feel at the end?","options":[{"id":"a","visual":"happy","alt":"happy"},{"id":"b","visual":"sad","alt":"sad"},{"id":"c","visual":"cross","alt":"cross"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["Ravi smiled the biggest smile."],"kind":"question"}]}'::jsonb,'published','reviewed',1,5) on conflict (id) do update set title=excluded.title, description=excluded.description, configuration=excluded.configuration, status=excluded.status, review_status=excluded.review_status, version=excluded.version, estimated_duration=excluded.estimated_duration;
