insert into public.activities (id,title,description,domain_id,world,engine_type,age_band,difficulty,configuration,status,review_status,version,estimated_duration) values ('story-tara-and-the-wobbly-tooth','Tara and the Wobbly Tooth','Listen to a story about a wobbly tooth, then answer questions about feelings and reasons.','early-literacy','conversation-cafe','story-listen','confident-learner',2,'{"id":"story-tara-and-the-wobbly-tooth","title":"Tara and the Wobbly Tooth","description":"Listen to a story about a wobbly tooth, then answer questions about feelings and reasons.","world":"conversation-cafe","domain":"early-literacy","objectiveIds":["LIT-LST-03"],"ageBand":"confident-learner","difficulty":2,"instructions":"Listen to the whole story. Then I will ask you some questions.","audioInstructions":"Listen to the whole story. Then I will ask you some questions.","estimatedMinutes":5,"feedback":{"correct":["Good thinking!","You noticed something interesting!","Lovely work!","Yes, you did it!"],"encourage":["Let''s try together.","Would you like a little hint?","Let''s look at it another way.","Nice try! One more go."],"complete":["You worked hard on that.","What a wonderful adventure!","Thank you for playing with me."]},"accessibility":{"requiresSpeech":false,"tapAlternative":true,"reducedMotionSafe":true},"media":[],"completion":{"minRoundsCompleted":2},"frameworkMappings":[{"frameworkId":"eyfs","reference":"Literacy","mappingType":"aligns"},{"frameworkId":"ncf-fs","reference":"Language and literacy","mappingType":"aligns"},{"frameworkId":"elof","reference":"Language and literacy","mappingType":"partial"}],"characterId":"otto","tags":["story","feelings"],"status":"published","reviewStatus":"reviewed","version":1,"presentation":"words","engine":"story-listen","rounds":[{"id":"p1","kind":"page","prompt":"Tara had a wobbly tooth. It wiggled when she touched it with her tongue.","display":"👧🦷","hints":[]},{"id":"p2","kind":"page","prompt":"At snack time, her mum gave her a crunchy apple. Tara put it down. She was worried that biting would hurt.","display":"🍎😟","hints":[]},{"id":"p3","kind":"page","prompt":"Her big brother Sam smiled and showed her the gap in his teeth. ''My tooth came out last week,'' he said. ''It did not hurt at all.''","display":"👦😁","hints":[]},{"id":"p4","kind":"page","prompt":"Tara took a small bite of the apple. Pop! Her tooth came out, and it did not hurt one bit.","display":"🍎🦷","hints":[]},{"id":"p5","kind":"page","prompt":"Tara grinned. Now she had a gap just like Sam, and she felt very brave.","display":"👧😁","hints":[]},{"id":"q1","prompt":"Why did Tara put the apple down?","options":[{"id":"a","visual":"she was worried it would hurt","alt":"she was worried it would hurt"},{"id":"b","visual":"she did not like apples","alt":"she did not like apples"},{"id":"c","visual":"she was full","alt":"she was full"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["Think about the words ''worried that biting would hurt''."],"kind":"question"},{"id":"q2","prompt":"How did Sam help Tara?","options":[{"id":"a","visual":"he showed her his gap and said it did not hurt","alt":"he showed her his gap and said it did not hurt"},{"id":"b","visual":"he ate her apple","alt":"he ate her apple"},{"id":"c","visual":"he laughed at her","alt":"he laughed at her"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["Sam showed Tara the gap in his teeth."],"kind":"question"},{"id":"q3","prompt":"What happened when Tara bit the apple?","options":[{"id":"a","visual":"her tooth came out","alt":"her tooth came out"},{"id":"b","visual":"her tooth hurt","alt":"her tooth hurt"},{"id":"c","visual":"the apple fell","alt":"the apple fell"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["Pop! Something came out when she took a small bite."],"kind":"question"},{"id":"q4","prompt":"How did Tara feel at the end?","options":[{"id":"a","visual":"brave and happy","alt":"brave and happy"},{"id":"b","visual":"worried and sad","alt":"worried and sad"},{"id":"c","visual":"angry","alt":"angry"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["She grinned and felt very brave."],"kind":"question"}]}'::jsonb,'published','reviewed',1,5) on conflict (id) do update set title=excluded.title, description=excluded.description, configuration=excluded.configuration, status=excluded.status, review_status=excluded.review_status, version=excluded.version, estimated_duration=excluded.estimated_duration;
