insert into public.activities (id,title,description,domain_id,world,engine_type,age_band,difficulty,configuration,status,review_status,version,estimated_duration) values ('story-kabir-and-the-big-race','Kabir and the Big Race','Listen to a story about a race, then answer questions about what happened and why.','early-literacy','conversation-cafe','story-listen','confident-learner',3,'{"id":"story-kabir-and-the-big-race","title":"Kabir and the Big Race","description":"Listen to a story about a race, then answer questions about what happened and why.","world":"conversation-cafe","domain":"early-literacy","objectiveIds":["LIT-LST-03"],"ageBand":"confident-learner","difficulty":3,"instructions":"Listen to the whole story. Then I will ask you some questions.","audioInstructions":"Listen to the whole story. Then I will ask you some questions.","estimatedMinutes":5,"feedback":{"correct":["Good thinking!","You noticed something interesting!","Lovely work!","Yes, you did it!"],"encourage":["Let''s try together.","Would you like a little hint?","Let''s look at it another way.","Nice try! One more go."],"complete":["You worked hard on that.","What a wonderful adventure!","Thank you for playing with me."]},"accessibility":{"requiresSpeech":false,"tapAlternative":true,"reducedMotionSafe":true},"media":[],"completion":{"minRoundsCompleted":2},"frameworkMappings":[{"frameworkId":"eyfs","reference":"Literacy","mappingType":"aligns"},{"frameworkId":"ncf-fs","reference":"Language and literacy","mappingType":"aligns"},{"frameworkId":"elof","reference":"Language and literacy","mappingType":"partial"}],"characterId":"otto","tags":["story","feelings","perseverance"],"status":"published","reviewStatus":"reviewed","version":1,"presentation":"words","engine":"story-listen","rounds":[{"id":"p1","kind":"page","prompt":"It was sports day. Kabir lined up with his friends for the big race.","display":"🏃👦","hints":[]},{"id":"p2","kind":"page","prompt":"''Ready, steady, go!'' Everyone ran fast. But Kabir tripped on a stone and fell down.","display":"💨😮","hints":[]},{"id":"p3","kind":"page","prompt":"His knee felt sore, and he wanted to stop. But he took a deep breath and got up.","display":"🧒🩹","hints":[]},{"id":"p4","kind":"page","prompt":"Kabir ran as fast as he could. He was the last to cross the line.","display":"🏁","hints":[]},{"id":"p5","kind":"page","prompt":"His friends clapped and cheered. ''Well done for not giving up!'' they said. Kabir felt proud.","display":"👏😊","hints":[]},{"id":"q1","prompt":"What happened to Kabir in the race?","options":[{"id":"a","visual":"he tripped and fell","alt":"he tripped and fell"},{"id":"b","visual":"he won the race","alt":"he won the race"},{"id":"c","visual":"he went home","alt":"he went home"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["Kabir tripped on a stone."],"kind":"question"},{"id":"q2","prompt":"Why did his friends cheer?","options":[{"id":"a","visual":"he did not give up","alt":"he did not give up"},{"id":"b","visual":"he came first","alt":"he came first"},{"id":"c","visual":"he was the tallest","alt":"he was the tallest"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["They said, ''Well done for not giving up!''"],"kind":"question"},{"id":"q3","prompt":"How did Kabir feel at the end?","options":[{"id":"a","visual":"proud","alt":"proud"},{"id":"b","visual":"bored","alt":"bored"},{"id":"c","visual":"scared","alt":"scared"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["The story told us Kabir felt proud."],"kind":"question"},{"id":"q4","prompt":"What can we learn from this story?","options":[{"id":"a","visual":"keep trying even when it is hard","alt":"keep trying even when it is hard"},{"id":"b","visual":"never run in a race","alt":"never run in a race"},{"id":"c","visual":"it is bad to come last","alt":"it is bad to come last"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["Think about why his friends were pleased with Kabir."],"kind":"question"}]}'::jsonb,'published','reviewed',1,5) on conflict (id) do update set title=excluded.title, description=excluded.description, configuration=excluded.configuration, status=excluded.status, review_status=excluded.review_status, version=excluded.version, estimated_duration=excluded.estimated_duration;
insert into public.activity_objectives (activity_id,objective_id,is_primary) values ('story-kabir-and-the-big-race','LIT-LST-03',true) on conflict (activity_id,objective_id) do update set is_primary=excluded.is_primary;
insert into public.activities (id,title,description,domain_id,world,engine_type,age_band,difficulty,configuration,status,review_status,version,estimated_duration) values ('story-the-clever-crow','The Clever Crow','Listen to a story about a thirsty crow, make a prediction, and work out what the story teaches.','early-literacy','conversation-cafe','story-listen','young-problem-solver',3,'{"id":"story-the-clever-crow","title":"The Clever Crow","description":"Listen to a story about a thirsty crow, make a prediction, and work out what the story teaches.","world":"conversation-cafe","domain":"early-literacy","objectiveIds":["LIT-LST-04"],"ageBand":"young-problem-solver","difficulty":3,"instructions":"Listen to the story. I will stop to ask what you think happens next.","audioInstructions":"Listen to the story. I will stop to ask what you think happens next.","estimatedMinutes":6,"feedback":{"correct":["Good thinking!","You noticed something interesting!","Lovely work!","Yes, you did it!"],"encourage":["Let''s try together.","Would you like a little hint?","Let''s look at it another way.","Nice try! One more go."],"complete":["You worked hard on that.","What a wonderful adventure!","Thank you for playing with me."]},"accessibility":{"requiresSpeech":false,"tapAlternative":true,"reducedMotionSafe":true},"media":[],"completion":{"minRoundsCompleted":2},"frameworkMappings":[{"frameworkId":"eyfs","reference":"Literacy","mappingType":"aligns"},{"frameworkId":"ncf-fs","reference":"Language and literacy","mappingType":"aligns"},{"frameworkId":"elof","reference":"Language and literacy","mappingType":"partial"}],"characterId":"otto","tags":["story","thinking","prediction"],"status":"published","reviewStatus":"reviewed","version":1,"presentation":"words","engine":"story-listen","rounds":[{"id":"p1","kind":"page","prompt":"It was a very hot day, and a crow was very thirsty. He flew here and there looking for water.","display":"🐦☀️","hints":[]},{"id":"p2","kind":"page","prompt":"At last he found a tall jug with a little water at the bottom. But the jug was so narrow that his beak could not reach it.","display":"🏺🐦","hints":[]},{"id":"q1","prompt":"What do you think the crow will do?","options":[{"id":"a","visual":"think of a clever way to reach the water","alt":"think of a clever way to reach the water"},{"id":"b","visual":"give up and fly away","alt":"give up and fly away"},{"id":"c","visual":"break the jug with his beak","alt":"break the jug with his beak"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["The crow is a clever bird. What could make the water come higher?"],"kind":"question"},{"id":"p3","kind":"page","prompt":"The crow looked around and saw some small pebbles. He picked up one pebble at a time and dropped it into the jug.","display":"🪨🐦","hints":[]},{"id":"p4","kind":"page","prompt":"Plop! Plop! Plop! Each pebble took up some room, and the water slowly rose higher and higher, until the crow could drink at last.","display":"🪨💧","hints":[]},{"id":"q2","prompt":"Why could the crow not drink at first?","options":[{"id":"a","visual":"the jug was narrow and the water was low","alt":"the jug was narrow and the water was low"},{"id":"b","visual":"the water was dirty","alt":"the water was dirty"},{"id":"c","visual":"the jug was empty","alt":"the jug was empty"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["The jug was narrow, and there was only a little water at the bottom."],"kind":"question"},{"id":"q3","prompt":"Why did the water rise?","options":[{"id":"a","visual":"the pebbles took up room in the jug","alt":"the pebbles took up room in the jug"},{"id":"b","visual":"it began to rain","alt":"it began to rain"},{"id":"c","visual":"the crow poured more water in","alt":"the crow poured more water in"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["Each pebble took up some room. Where did the water have to go?"],"kind":"question"},{"id":"q4","prompt":"What does this story teach us?","options":[{"id":"a","visual":"to think carefully and keep trying","alt":"to think carefully and keep trying"},{"id":"b","visual":"to fly away from problems","alt":"to fly away from problems"},{"id":"c","visual":"to be afraid of jugs","alt":"to be afraid of jugs"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["The crow did not give up. He thought of a plan."],"kind":"question"}]}'::jsonb,'published','reviewed',1,6) on conflict (id) do update set title=excluded.title, description=excluded.description, configuration=excluded.configuration, status=excluded.status, review_status=excluded.review_status, version=excluded.version, estimated_duration=excluded.estimated_duration;
insert into public.activity_objectives (activity_id,objective_id,is_primary) values ('story-the-clever-crow','LIT-LST-04',true) on conflict (activity_id,objective_id) do update set is_primary=excluded.is_primary;
insert into public.activities (id,title,description,domain_id,world,engine_type,age_band,difficulty,configuration,status,review_status,version,estimated_duration) values ('story-anaya-and-the-library-book','Anaya and the Library Book','Listen to a story about telling the truth, then answer questions about what the characters do and why.','early-literacy','conversation-cafe','story-listen','young-problem-solver',3,'{"id":"story-anaya-and-the-library-book","title":"Anaya and the Library Book","description":"Listen to a story about telling the truth, then answer questions about what the characters do and why.","world":"conversation-cafe","domain":"early-literacy","objectiveIds":["LIT-LST-04"],"ageBand":"young-problem-solver","difficulty":3,"instructions":"Listen to the story. I will stop to ask what you think.","audioInstructions":"Listen to the story. I will stop to ask what you think.","estimatedMinutes":6,"feedback":{"correct":["Good thinking!","You noticed something interesting!","Lovely work!","Yes, you did it!"],"encourage":["Let''s try together.","Would you like a little hint?","Let''s look at it another way.","Nice try! One more go."],"complete":["You worked hard on that.","What a wonderful adventure!","Thank you for playing with me."]},"accessibility":{"requiresSpeech":false,"tapAlternative":true,"reducedMotionSafe":true},"media":[],"completion":{"minRoundsCompleted":2},"frameworkMappings":[{"frameworkId":"eyfs","reference":"Literacy","mappingType":"aligns"},{"frameworkId":"ncf-fs","reference":"Language and literacy","mappingType":"aligns"},{"frameworkId":"elof","reference":"Language and literacy","mappingType":"partial"}],"characterId":"otto","tags":["story","honesty","thinking"],"status":"published","reviewStatus":"reviewed","version":1,"presentation":"words","engine":"story-listen","rounds":[{"id":"p1","kind":"page","prompt":"Anaya borrowed a book about dinosaurs from the school library. She loved it and read it every night.","display":"👧📖🦕","hints":[]},{"id":"p2","kind":"page","prompt":"One morning she looked in her bag, but the book was gone. Anaya felt a lump in her throat. She was scared she would be in trouble.","display":"🎒😟","hints":[]},{"id":"q1","prompt":"What do you think Anaya should do?","options":[{"id":"a","visual":"tell the librarian what happened","alt":"tell the librarian what happened"},{"id":"b","visual":"hide and say nothing","alt":"hide and say nothing"},{"id":"c","visual":"say she never borrowed it","alt":"say she never borrowed it"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["Which choice is honest, and also lets someone help?"],"kind":"question"},{"id":"p3","kind":"page","prompt":"Anaya took a deep breath and told the librarian the truth. ''I am sorry. I think I lost my book,'' she said.","display":"👧🗣️","hints":[]},{"id":"p4","kind":"page","prompt":"The librarian smiled kindly. ''Thank you for telling me. Let us look together.'' They found the book under the bus seat that very afternoon, and the bus driver had kept it safe.","display":"👩🚌📖","hints":[]},{"id":"q2","prompt":"Why was Anaya worried?","options":[{"id":"a","visual":"she had lost the library book","alt":"she had lost the library book"},{"id":"b","visual":"she did not like dinosaurs","alt":"she did not like dinosaurs"},{"id":"c","visual":"she was late for school","alt":"she was late for school"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["She looked in her bag but the book was gone."],"kind":"question"},{"id":"q3","prompt":"How did the librarian react?","options":[{"id":"a","visual":"she was kind and helped","alt":"she was kind and helped"},{"id":"b","visual":"she was very cross","alt":"she was very cross"},{"id":"c","visual":"she did not mind at all, and did nothing","alt":"she did not mind at all, and did nothing"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["The librarian smiled kindly and said, ''Let us look together.''"],"kind":"question"},{"id":"q4","prompt":"Why was telling the truth a good idea?","options":[{"id":"a","visual":"people could help her find the book","alt":"people could help her find the book"},{"id":"b","visual":"it made the book disappear","alt":"it made the book disappear"},{"id":"c","visual":"it meant she could keep the book","alt":"it meant she could keep the book"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["Because Anaya told the truth, the librarian could help look."],"kind":"question"}]}'::jsonb,'published','reviewed',1,6) on conflict (id) do update set title=excluded.title, description=excluded.description, configuration=excluded.configuration, status=excluded.status, review_status=excluded.review_status, version=excluded.version, estimated_duration=excluded.estimated_duration;
insert into public.activity_objectives (activity_id,objective_id,is_primary) values ('story-anaya-and-the-library-book','LIT-LST-04',true) on conflict (activity_id,objective_id) do update set is_primary=excluded.is_primary;
insert into public.activities (id,title,description,domain_id,world,engine_type,age_band,difficulty,configuration,status,review_status,version,estimated_duration) values ('help-the-mouse-find-the-cheese','Help the Mouse Find the Cheese','Walk the mouse along the path to the cheese.','logic-puzzles','puzzle-planet','maze','little-explorer',1,'{"id":"help-the-mouse-find-the-cheese","title":"Help the Mouse Find the Cheese","description":"Walk the mouse along the path to the cheese.","world":"puzzle-planet","domain":"logic-puzzles","objectiveIds":["LOG-MAZ-01"],"ageBand":"little-explorer","difficulty":1,"instructions":"Tap the square next to you, or use the arrows, to walk to the cheese.","audioInstructions":"Tap the square next to you, or use the arrows, to walk to the cheese.","estimatedMinutes":3,"feedback":{"correct":["Good thinking!","You noticed something interesting!","Lovely work!","Yes, you did it!"],"encourage":["Let''s try together.","Would you like a little hint?","Let''s look at it another way.","Nice try! One more go."],"complete":["You worked hard on that.","What a wonderful adventure!","Thank you for playing with me."]},"accessibility":{"requiresSpeech":false,"tapAlternative":true,"reducedMotionSafe":true},"media":[],"completion":{"minRoundsCompleted":2},"frameworkMappings":[{"frameworkId":"eyfs","reference":"Mathematics (number, numerical patterns)","mappingType":"aligns"},{"frameworkId":"elof","reference":"Cognition: mathematics development","mappingType":"partial"},{"frameworkId":"montessori","reference":"Mathematics: concrete to abstract","mappingType":"informs"}],"characterId":"pip","tags":["maze","path"],"realWorldMission":"Draw a maze on paper and solve it with your finger.","status":"published","reviewStatus":"reviewed","version":1,"presentation":"pictures","engine":"maze","rounds":[{"id":"r1","prompt":"Help the mouse get to the cheese!","grid":["#####","#S#G#","#.#.#","#...#","#####"],"mover":"🐭","goal":"🧀","hints":["Tap the square next to you, 