:"Sam","alt":"Sam"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["Sam has the dog, and Mia does not have the cat. Who is left?"]},{"id":"r2","prompt":"A ball is in one of three boxes: red, blue or green. It is not in the red box. It is not in the blue box. Which box is it in?","options":[{"id":"a","visual":"the green box","alt":"the green box"},{"id":"b","visual":"the red box","alt":"the red box"},{"id":"c","visual":"the blue box","alt":"the blue box"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["Cross out the red box and the blue box."]},{"id":"r3","prompt":"Ana is taller than Ben. Ben is taller than Cy. Who is the tallest?","options":[{"id":"a","visual":"Ana","alt":"Ana"},{"id":"b","visual":"Ben","alt":"Ben"},{"id":"c","visual":"Cy","alt":"Cy"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["Ana is taller than Ben, and Ben is taller than Cy."]},{"id":"r4","prompt":"It is not a dog. It is not a cat. It has fins and swims. What is it?","options":[{"id":"a","visual":"a fish","alt":"a fish"},{"id":"b","visual":"a dog","alt":"a dog"},{"id":"c","visual":"a cat","alt":"a cat"}],"correctIds":["a"],"acceptableIds":[],"openEnded":false,"hints":["Cross out the dog and the cat."]}]}'::jsonb,'published','reviewed',1,3) on conflict (id) do update set title=excluded.title, description=excluded.description, configuration=excluded.configuration, status=excluded.status, review_status=excluded.review_status, version=excluded.version, estimated_duration=excluded.estimated_duration;
